    None => format!("{head}…"),
}

findings.suggestion:
let head: String = text.chars().take(limit).collect();
match head.rfind(' ') {
    Some(space) => format!("{}…", &head[..space]),
    None => {
        let mut head = head;
        if head.is_empty() {
            String::new()
        } else {
            head.pop();
            format!("{head}…")
        }
    }
}
